BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE IF NOT EXISTS teachers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_user_id text UNIQUE,display_name varchar(120) NOT NULL,email varchar(254) NOT NULL,approved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT teachers_email_lowercase CHECK(email=lower(email)));
CREATE TABLE IF NOT EXISTS policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),teacher_id uuid NOT NULL REFERENCES teachers(id) ON DELETE CASCADE,title varchar(120) NOT NULL CHECK(char_length(btrim(title))>=4),subject varchar(100) NOT NULL CHECK(char_length(btrim(subject))>=2),category varchar(50) NOT NULL CHECK(category IN ('allowed_with_conditions','limited_use','not_allowed_for_specified_work')),summary varchar(280) NOT NULL CHECK(char_length(btrim(summary))>=10),policy_text text NOT NULL CHECK(char_length(btrim(policy_text))>=20),conditions text NOT NULL DEFAULT '',status varchar(12) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS policies_owner_updated_idx ON policies(teacher_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS policies_public_updated_idx ON policies(updated_at DESC) WHERE status='published';
CREATE INDEX IF NOT EXISTS policies_category_subject_idx ON policies(category,subject) WHERE status='published';
CREATE INDEX IF NOT EXISTS policies_title_trgm_idx ON policies USING gin(title gin_trgm_ops);
CREATE INDEX IF NOT EXISTS teachers_name_trgm_idx ON teachers USING gin(display_name gin_trgm_ops);
INSERT INTO teachers(id,auth_user_id,display_name,email,approved) VALUES('10000000-0000-4000-8000-000000000001',NULL,'Rulebook Demo Faculty','demo-faculty@example.invalid',false) ON CONFLICT(id) DO NOTHING;
INSERT INTO policies(id,teacher_id,title,subject,category,summary,policy_text,conditions,status) VALUES
('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','AI as a study partner, not a substitute','Computer Science','allowed_with_conditions','AI tools may help explain concepts and debug your own code, but submitted work must reflect your understanding.','DEMONSTRATION ONLY — not an official course rule. AI may explain programming concepts, suggest debugging approaches, or generate practice questions. Submitted code and explanations must reflect your understanding and follow actual assignment instructions.','Disclose AI assistance when required. Never submit generated code you cannot explain.','published'),
('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Limited AI use for written assignments','Academic Writing','limited_use','AI can support brainstorming and proofreading, while the core argument and analysis must be your own.','DEMONSTRATION ONLY — not an official course rule. AI may be used for topic exploration, outlining, or grammar issues. It may not replace your reasoning, source evaluation, or original argument. Follow the instructor’s actual instructions.','Cite sources independently and disclose AI use when required. Do not submit fabricated references.','published'),
('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','Independent work during assessments','Mathematics','not_allowed_for_specified_work','AI assistance is not permitted during assessments explicitly designated as independent work.','DEMONSTRATION ONLY — not an official course rule. For independent assessments, do not use AI to generate answers or provide live assistance. Ask the instructor if permitted tools are unclear.','This example applies only to the hypothetical assessment described here.','published') ON CONFLICT(id) DO NOTHING;
COMMIT;